import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Line, Bar, Pie } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, 
  BarElement, ArcElement, Title, Tooltip, Legend, Filler
} from 'chart.js';

// ChartJS components register pannanum
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Title, Tooltip, Legend, Filler);

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [searchQuery, setSearchQuery] = useState("");
  const [authData, setAuthData] = useState({ username: '', password: '', email: '' });
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);

   const stockList = [

    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },

    { name: "SBI", symbol: "SBIN.NS" },

    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },

    { name: "Reliance Industries", symbol: "RELIANCE.NS" },

    { name: "TCS", symbol: "TCS.NS" },

    { name: "Infosys", symbol: "INFY.NS" },

    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },

    { name: "Zomato", symbol: "ZOMATO.NS" },

    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },

    { name: "ITC", symbol: "ITC.NS" }

  ];

  const filteredStocks = stockList.filter(s => 
    s.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    s.symbol.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleAuth = async () => {
    const endpoint = isSignup ? "/auth/signup" : "/auth/login";
    try {
      await axios.post(`http://localhost:8000${endpoint}`, authData);
      if (isSignup) { alert("Signup Success! Login now."); setIsSignup(false); } 
      else { setIsLoggedIn(true); }
    } catch (err) { alert("Auth Failed: " + err.response?.data?.detail); }
  };

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => { setData(res.data); setLoading(false); })
      .catch(err => { console.error(err); setLoading(false); });
  };

  useEffect(() => { if (isLoggedIn) fetchData(selectedStock); }, [selectedStock, isLoggedIn]);

  // 📈 CHART DATA LOGIC
  const lineData = {
    labels: ['Day-5', 'Day-4', 'Day-3', 'Day-2', 'Day-1', 'Today'],
    datasets: [{
      label: 'Price Trend',
      data: data ? [data.current_price * 0.98, data.current_price * 0.99, data.current_price * 0.97, data.current_price * 1.01, data.current_price * 0.99, data.current_price] : [],
      borderColor: '#4facfe', backgroundColor: 'rgba(79, 172, 254, 0.1)', fill: true, tension: 0.4
    }]
  };

  const barData = {
    labels: ['Volatility', 'Momentum', 'Protection'],
    datasets: [{
      label: 'Risk Metrics %',
      data: data ? [parseFloat(data.volatility), 55, 85] : [],
      backgroundColor: ['#f85149', '#4facfe', '#22c55e'],
      borderRadius: 10
    }]
  };

  const pieData = {
    labels: ['Equities', 'Hedge', 'Cash'],
    datasets: [{
      data: data?.regime === "STRESS" ? [40, 50, 10] : [70, 10, 20],
      backgroundColor: ['#4facfe', '#f85149', '#e2e8f0'],
      borderWidth: 0
    }]
  };

  if (!isLoggedIn) {
    return (
      <div style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`, backgroundSize: 'cover', backgroundPosition: 'center', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" }}>
        <div style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', borderRadius: '30px', width: '900px', display: 'flex', gap: '40px', color: 'white' }}>
          <div style={{ flex: 1 }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', color: '#00f2fe' }}>QuantShield</h1>
             <p>Financial Portfolio Optimization and Risk Forecasting System</p>
          </div>
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px' }}>
            <h2 style={{ marginBottom: '20px' }}>{isSignup ? "REGISTER" : "LOGIN"}</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop: '15px' }}>{isSignup ? "SIGN UP" : "SIGN IN"}</button>
            <p onClick={() => setIsSignup(!isSignup)} style={{ textAlign: 'center', marginTop: '15px', cursor: 'pointer', color: '#00f2fe' }}>{isSignup ? "Login" : "Register"}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      {/* Sidebar Navigation */}
      <div style={{ width: '260px', background: 'white', padding: '30px 20px', borderRight: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
        <h2 style={{ color: '#4facfe', fontWeight: '800', marginBottom: '40px' }}>🛡️ QuantShield</h2>
        {["Dashboard", "Analytics", "Stocks", "Settings"].map(tab => (
          <div key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab === tab ? '#f4f7fe' : 'transparent', color: activeTab === tab ? '#4facfe' : '#64748b', padding: '12px 15px', borderRadius: '10px', fontWeight: 'bold', marginBottom: '10px', cursor: 'pointer' }}>
             {tab === "Dashboard" ? "📁" : tab === "Analytics" ? "📈" : tab === "Stocks" ? "💹" : "⚙️"} {tab}
          </div>
        ))}
        <div style={{ marginTop: 'auto', padding: '15px', color: '#f85149', cursor: 'pointer', fontWeight: 'bold' }} onClick={() => setIsLoggedIn(false)}>Logout</div>
      </div>

      {/* Main Content Area */}
      <div style={{ flex: 1, padding: '40px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <h1 style={{ fontSize: '28px', fontWeight: '800', color: '#1e293b' }}>{activeTab}</h1>
          <div style={{ display: 'flex', gap: '15px', position: 'relative' }}>
             <input type="text" placeholder="Search Stocks..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={{ padding: '10px 20px', borderRadius: '30px', border: '1px solid #e2e8f0', width: '250px' }} />
             {searchQuery && (
               <div style={{ position: 'absolute', top: '50px', background: 'white', width: '100%', borderRadius: '10px', boxShadow: '0 10px 20px rgba(0,0,0,0.1)', zIndex: 10 }}>
                 {filteredStocks.map(s => <div key={s.symbol} onClick={() => { setSelectedStock(s.symbol); setSearchQuery(""); setActiveTab("Dashboard"); }} style={{ padding: '10px', cursor: 'pointer' }}>{s.name}</div>)}
               </div>
             )}
          </div>
        </div>

        {/* TABS CONTENT */}
        {activeTab === "Dashboard" && data && (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
              <MiniCard title="Current Price" value={`₹${data.current_price}`} color="#4facfe" />
              <MiniCard title="Volatility" value={data.volatility} color="#f85149" />
              <MiniCard title="BSI Momentum" value={data.bsi_score} color="#d2a8ff" />
              <MiniCard title="Decision" value={data.decision} color="#22c55e" />
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '30px' }}>
              {/* 🟢 LINE GRAPH */}
              <div style={{ background: 'white', padding: '25px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
                <h3>Live Price Momentum</h3>
                <div style={{ height: '300px' }}><Line data={lineData} options={{ maintainAspectRatio: false }} /></div>
              </div>
              {/* 🍕 PIE CHART */}
              <div style={{ background: 'white', padding: '25px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', textAlign: 'center' }}>
                <h3>Asset Allocation</h3>
                <div style={{ height: '230px', display: 'flex', justifyContent: 'center' }}><Pie data={pieData} /></div>
                <p style={{ marginTop: '15px', color: '#64748b' }}>Regime: <b>{data.regime}</b></p>
              </div>
            </div>
          </>
        )}

        {activeTab === "Analytics" && (
          <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
            <h3>📊 Advanced Risk Intelligence</h3>
            <div style={{ height: '400px', marginTop: '20px' }}>
              <Bar data={barData} options={{ maintainAspectRatio: false }} />
            </div>
          </div>
        )}

        {activeTab === "Stocks" && (
           <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
             <h3>💹 Watchlist Performance</h3>
             <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
               <thead>
                 <tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b' }}>
                   <th style={{ padding: '15px', textAlign: 'left' }}>Stock</th>
                   <th style={{ textAlign: 'left' }}>Price</th>
                   <th style={{ textAlign: 'left' }}>Action</th>
                 </tr>
               </thead>
               <tbody>
                 {stockList.map(s => (
                   <tr key={s.symbol} style={{ borderBottom: '1px solid #f1f5f9' }}>
                     <td style={{ padding: '15px', fontWeight: 'bold' }}>{s.name}</td>
                     <td>₹{s.symbol === "HDFCBANK.NS" ? "816.70" : "1,140.25"}</td>
                     <td><button onClick={() => { setSelectedStock(s.symbol); setActiveTab("Dashboard"); }} style={{ background: '#4facfe', color: 'white', border: 'none', padding: '5px 15px', borderRadius: '5px', cursor: 'pointer' }}>Analyze</button></td>
                   </tr>
                 ))}
               </tbody>
             </table>
           </div>
        )}

        {activeTab === "Settings" && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '25px' }}>
             <div style={{ background: 'white', padding: '30px', borderRadius: '24px', textAlign: 'center' }}>
                <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#4facfe', margin: '0 auto 20px', color: 'white', fontSize: '30px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>S</div>
                <h3>Suresh M</h3>
                <p>QuantShield Verified User</p>
             </div>
             <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
                <h4>Account Preferences</h4>
                <p>Ghost Hedge Mode: <b style={{ color: '#22c55e' }}>ENABLED</b></p>
                <p>Real-time Sync: <b style={{ color: '#4facfe' }}>ACTIVE</b></p>
                <button style={{ padding: '10px 20px', background: '#f4f7fe', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Edit Profile</button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
}

function MiniCard({ title, value, color }) {
  return (
    <div style={{ background: 'white', padding: '25px', borderRadius: '20px', border: '1px solid #f1f5f9', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
      <div style={{ color: '#64748b', fontSize: '13px', marginBottom: '5px', fontWeight: 'bold' }}>{title}</div>
      <div style={{ fontSize: '24px', fontWeight: '800', color: '#1e293b' }}>{value}</div>
      <div style={{ marginTop: '10px', width: '40px', height: '4px', background: color, borderRadius: '2px' }}></div>
    </div>
  );
}

export default App;
